/**
 * Location lookup over the owner's `locations.db`, committed as `src/data/locations.ts` (generated by
 * `scripts/import-locations.py`). Work package `locations-select`, part of #12.
 *
 * The user picks a country, then a place. Each row is one point for a country, a state or a city, so the
 * coordinates are used as they are (a birth far from the point shifts the Ascendant; the UI shows them).
 * The UTC offset is NOT here: it depends on the birth date and comes from the row's IANA zone through
 * `computeTimezoneOffset` (`src/core/timezone.ts`).
 */
import { LOCATIONS } from '../data/locations.js';
import type { LocationRecord } from '../data/locations.js';

export type { LocationRecord };

/** A birth before this year is outside the range where IANA says its data is reliable. */
export const PRE_IANA_RELIABLE_YEAR = 1970;

const BY_ID: ReadonlyMap<number, LocationRecord> = new Map(LOCATIONS.map((l) => [l.id, l]));

const BY_COUNTRY: ReadonlyMap<string, readonly LocationRecord[]> = (() => {
  const map = new Map<string, LocationRecord[]>();
  for (const l of LOCATIONS) {
    const list = map.get(l.country);
    if (list) list.push(l);
    else map.set(l.country, [l]);
  }
  for (const list of map.values()) {
    // The country-only row first, then the places by name.
    list.sort((a, b) => (a.place === null ? -1 : b.place === null ? 1 : a.place.localeCompare(b.place, 'en')));
  }
  return map;
})();

/** Every country in the data, sorted by name. */
export function listCountries(): string[] {
  return [...BY_COUNTRY.keys()].sort((a, b) => a.localeCompare(b, 'en'));
}

/** The rows of one country: its country-only row (place null) first, then the places by name. Unknown country: `[]`. */
export function listPlaces(country: string): readonly LocationRecord[] {
  return BY_COUNTRY.get(country) ?? [];
}

/** One row by its stable id (the `locations.db` id), or `undefined`. */
export function getLocation(id: number): LocationRecord | undefined {
  return BY_ID.get(id);
}

/** `GET /api/locations` body: every country with its places. */
export function listLocationsByCountry(): Array<{
  country: string;
  places: Array<Pick<LocationRecord, 'id' | 'country' | 'place' | 'latitude' | 'longitude' | 'timezone'>>;
}> {
  return listCountries().map((country) => ({
    country,
    places: listPlaces(country).map(({ id, country: c, place, latitude, longitude, timezone }) => ({
      id,
      country: c,
      place,
      latitude,
      longitude,
      timezone,
    })),
  }));
}
